//! Windows platform operations following libuv and Node.
use super::{OpenMode,ShellConfig};use crate::errors::Failure;use serde_json::{Map,Value};use std::{collections::hash_map::RandomState,ffi::OsStr,fs::{File,Metadata},hash::{BuildHasher,Hasher},io,os::windows::{ffi::OsStrExt,fs::FileExt,io::{AsRawHandle,FromRawHandle},process::CommandExt},path::Path,process::{Child,Command,ExitStatus,Stdio},sync::LazyLock,sync::atomic::{AtomicU64,Ordering},time::UNIX_EPOCH};use windows_sys::Win32::Foundation::INVALID_HANDLE_VALUE;use windows_sys::Win32::Storage::FileSystem::{CREATE_ALWAYS,CreateFileW,FILE_APPEND_DATA,FILE_ATTRIBUTE_NORMAL,FILE_FLAG_BACKUP_SEMANTICS,FILE_GENERIC_READ,FILE_GENERIC_WRITE,FILE_SHARE_DELETE,FILE_SHARE_READ,FILE_SHARE_WRITE,FILE_WRITE_DATA,MOVEFILE_REPLACE_EXISTING,MoveFileExW,OPEN_ALWAYS,OPEN_EXISTING};use windows_sys::Win32::System::JobObjects::{AssignProcessToJobObject,CreateJobObjectW,JOB_OBJECT_LIMIT_BREAKAWAY_OK,JOB_OBJECT_LIMIT_DIE_ON_UNHANDLED_EXCEPTION,JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,JOB_OBJECT_LIMIT_SILENT_BREAKAWAY_OK,JOBOBJECT_EXTENDED_LIMIT_INFORMATION,JobObjectExtendedLimitInformation,SetInformationJobObject};use windows_sys::Win32::System::Threading::CREATE_NO_WINDOW;
pub fn error_name(e:&io::Error)->&'static str{let Some(c)=e.raw_os_error()else{return "UNKNOWN"};match c{1=>"EISDIR",2|3|15|123|161|4392=>"ENOENT",4=>"EMFILE",5|1314=>"EPERM",6=>"EBADF",8|14=>"ENOMEM",17=>"EXDEV",19=>"EROFS",32|33=>"EBUSY",39|82|112=>"ENOSPC",50=>"ENOTSUP",80|183=>"EEXIST",87|131|1464=>"EINVAL",145=>"ENOTEMPTY",206=>"ENAMETOOLONG",267=>"ENOTDIR",740|998|1920=>"EACCES",1921=>"ELOOP",_=>"UNKNOWN"}}
pub const PATH_SEPARATOR:&str="\\";pub fn read_at(f:&File,b:&mut[u8],o:u64)->io::Result<usize>{f.seek_read(b,o)}pub fn mtime(m:&Metadata)->(i64,i64){match m.modified().ok().and_then(|t|t.duration_since(UNIX_EPOCH).ok()){Some(d)=>(d.as_secs()as i64,d.subsec_nanos()as i64),None=>(0,0)}}pub fn identity(_:&Metadata)->(u64,u64){(0,0)}
pub fn tmpdir()->String{let var=|k:&str|std::env::var(k).ok().filter(|v|!v.is_empty());let mut p=var("TEMP").or_else(||var("TMP")).unwrap_or_else(||format!("{}\\temp",var("SystemRoot").or_else(||var("windir")).unwrap_or_default()));if p.len()>1&&p.ends_with('\\')&&!p.ends_with(":\\"){p.pop()}p}pub fn home()->String{std::env::var("USERPROFILE").unwrap_or_default()}fn wide(s:&str)->Vec<u16>{OsStr::new(s).encode_wide().chain(std::iter::once(0)).collect()}
pub fn mkdtemp(prefix:&str)->io::Result<String>{const CHARS:&[u8]=b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";static COUNTER:AtomicU64=AtomicU64::new(0);let state=RandomState::new();for _ in 0..1000{let mut h=state.build_hasher();h.write_u64(COUNTER.fetch_add(1,Ordering::Relaxed));let mut n=h.finish();let mut p=prefix.to_string();for _ in 0..6{p.push(CHARS[(n%CHARS.len()as u64)as usize]as char);n/=CHARS.len()as u64}match std::fs::create_dir(&p){Ok(())=>return Ok(p),Err(e)if e.kind()==io::ErrorKind::AlreadyExists=>continue,Err(e)=>return Err(e)}}Err(io::Error::from_raw_os_error(80))}
pub fn open_reader(path:&str,no_follow:bool)->Result<File,Failure>{if no_follow&&std::fs::symlink_metadata(path).is_ok_and(|m|m.file_type().is_symlink()){return Err(Failure::new("SYMLINK","Refusing to follow a symbolic link").path(path))}if std::fs::metadata(path).is_ok_and(|m|m.is_dir()){return Err(Failure::new("EISDIR","EISDIR: illegal operation on a directory, read").path(path))}File::open(path).map_err(|e|Failure::io(&e,"open",path))}
pub fn open(path:&str,mode:OpenMode)->io::Result<File>{let(access,disposition)=match mode{OpenMode::Write=>(FILE_GENERIC_WRITE,CREATE_ALWAYS),OpenMode::Append=>((FILE_GENERIC_WRITE&!FILE_WRITE_DATA)|FILE_APPEND_DATA,OPEN_ALWAYS),OpenMode::ReadWrite=>(FILE_GENERIC_READ|FILE_GENERIC_WRITE,OPEN_EXISTING)};let name=wide(path);let handle=unsafe{CreateFileW(name.as_ptr(),access,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,std::ptr::null(),disposition,FILE_ATTRIBUTE_NORMAL|FILE_FLAG_BACKUP_SEMANTICS,std::ptr::null_mut())};if handle==INVALID_HANDLE_VALUE{let e=io::Error::last_os_error();if e.raw_os_error()==Some(80)&&!matches!(mode,OpenMode::ReadWrite){return Err(io::Error::from_raw_os_error(1))}return Err(e)}Ok(unsafe{File::from_raw_handle(handle as _)})}
pub fn realpath(path:&str)->io::Result<String>{let p=std::fs::canonicalize(path)?.to_string_lossy().into_owned();Ok(if let Some(unc)=p.strip_prefix("\\\\?\\UNC\\"){format!("\\\\{unc}")}else{p.strip_prefix("\\\\?\\").map(str::to_string).unwrap_or(p)})}pub fn rename(a:&str,b:&str)->io::Result<()>{let(a,b)=(wide(a),wide(b));if unsafe{MoveFileExW(a.as_ptr(),b.as_ptr(),MOVEFILE_REPLACE_EXISTING)}==0{return Err(io::Error::last_os_error())}Ok(())}pub fn remove_file(path:&str)->io::Result<()>{match std::fs::remove_file(path){Err(e)if e.kind()==io::ErrorKind::PermissionDenied=>{let mut p=std::fs::metadata(path)?.permissions();#[allow(clippy::permissions_set_readonly_false)]p.set_readonly(false);std::fs::set_permissions(path,p)?;std::fs::remove_file(path)},x=>x}}pub fn not_a_directory()->io::Error{io::Error::from_raw_os_error(267)}fn path_exists(p:&str)->bool{Path::new(p).symlink_metadata().is_ok()}
fn is_legacy_wsl_bash(p:&str)->bool{let s=p.replace('/','\\').to_lowercase();let mut c=s.chars();c.next().is_some_and(|x|x.is_ascii_lowercase())&&matches!(c.as_str(),":\\windows\\system32\\bash.exe"|":\\windows\\sysnative\\bash.exe")}fn bash_config(p:&str)->ShellConfig{ShellConfig{program:p.into(),args:vec![if is_legacy_wsl_bash(p){"-s"}else{"-c"}.into()],command_on_stdin:is_legacy_wsl_bash(p)}}fn where_bash()->Option<String>{let o=Command::new("where").arg("bash.exe").creation_flags(CREATE_NO_WINDOW).stdin(Stdio::null()).stderr(Stdio::null()).output().ok()?;if !o.status.success(){return None}let p=String::from_utf8_lossy(&o.stdout).trim().lines().next()?.trim().to_string();path_exists(&p).then_some(p)}
pub fn shell_config(shell_path:Option<&str>)->Result<ShellConfig,Failure>{if let Some(p)=shell_path{if path_exists(p){return Ok(bash_config(p))}return Err(Failure::new("shell_unavailable",format!("Custom shell path not found: {p}")))}let candidates=["ProgramFiles","ProgramFiles(x86)"].iter().filter_map(|v|std::env::var(v).ok().map(|d|format!("{d}\\Git\\bin\\bash.exe"))).collect::<Vec<_>>();if let Some(p)=candidates.iter().find(|p|path_exists(p)){return Ok(bash_config(p))}if let Some(p)=where_bash(){return Ok(bash_config(&p))}Err(Failure::new("shell_unavailable",format!("No bash shell found. Options:\n  1. Install Git for Windows: https://git-scm.com/download/win\n  2. Add your bash to PATH (Cygwin, MSYS2, etc.)\n  3. Configure an explicit shellPath\n\nSearched Git Bash in:\n{}",candidates.join("\n"))))}
pub fn quote_argument(a:&str)->String{if a.is_empty(){return "\"\"".into()}if !a.contains([' ','\t','"']){return a.into()}if !a.contains(['"','\\']){return format!("\"{a}\"")}let mut reversed=Vec::new();let mut quote_hit=true;for c in a.chars().rev(){reversed.push(c);if quote_hit&&c=='\\'{reversed.push('\\')}else if c=='"'{quote_hit=true;reversed.push('\\')}else{quote_hit=false}}let mut q=String::from("\"");q.extend(reversed.into_iter().rev());q.push('"');q}
const REQUIRED:[&str;11]=["HOMEDRIVE","HOMEPATH","LOGONSERVER","PATH","SYSTEMDRIVE","SYSTEMROOT","TEMP","USERDOMAIN","USERNAME","USERPROFILE","WINDIR"];
fn child_environment(env:&Map<String,Value>,inherit:bool)->Vec<(String,String)>{let mut entries:Vec<(String,String)>=Vec::new();let mut set=|k:String,v:String|match entries.iter_mut().find(|(n,_)|*n==k){Some(e)=>e.1=v,None=>entries.push((k,v))};if inherit{for(k,v)in std::env::vars_os(){set(k.to_string_lossy().into_owned(),v.to_string_lossy().into_owned())}}for(k,v)in env{if let Some(v)=v.as_str(){set(k.clone(),v.to_string())}}entries.sort_by(|(a,_),(b,_)|a.encode_utf16().cmp(b.encode_utf16()));let mut seen=std::collections::HashSet::new();entries.retain(|(n,_)|seen.insert(n.to_uppercase()));for required in REQUIRED{if !entries.iter().any(|(n,_)|n.eq_ignore_ascii_case(required)){if let Ok(v)=std::env::var(required){entries.push((required.to_string(),v))}}}entries}
pub fn configure(command:&mut Command,args:&[String],env:&Map<String,Value>,inherit:bool){for a in args{command.raw_arg(quote_argument(a))}command.env_clear();for(k,v)in child_environment(env,inherit){command.env(k,v);}command.creation_flags(CREATE_NO_WINDOW)}
fn job()->Option<isize>{static JOB:LazyLock<Option<isize>>=LazyLock::new(||unsafe{let job=CreateJobObjectW(std::ptr::null(),std::ptr::null());if job.is_null(){return None}let mut info:JOBOBJECT_EXTENDED_LIMIT_INFORMATION=std::mem::zeroed();info.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_BREAKAWAY_OK|JOB_OBJECT_LIMIT_SILENT_BREAKAWAY_OK|JOB_OBJECT_LIMIT_DIE_ON_UNHANDLED_EXCEPTION|JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;SetInformationJobObject(job,JobObjectExtendedLimitInformation,(&info as *const JOBOBJECT_EXTENDED_LIMIT_INFORMATION).cast(),std::mem::size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>()as u32);Some(job as isize)});*JOB}pub fn after_spawn(child:&Child){if let Some(job)=job(){unsafe{AssignProcessToJobObject(job as _,child.as_raw_handle()as _)}}}pub fn kill_tree(pid:u32){let root=std::env::var("SystemRoot").unwrap_or_else(|_|"C:\\Windows".into());let _=Command::new(format!("{root}\\System32\\taskkill.exe")).args(["/F","/T","/PID",&pid.to_string()]).creation_flags(CREATE_NO_WINDOW).stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null()).spawn();}pub fn exit_code(s:ExitStatus)->i64{i64::from(s.code().unwrap_or(1)as u32)}
#[cfg(test)]mod tests{use super::quote_argument;#[test]fn quotes_arguments_like_libuv(){assert_eq!(quote_argument(""),"\"\"");assert_eq!(quote_argument("plain"),"plain");assert_eq!(quote_argument("a b"),"\"a b\"");assert_eq!(quote_argument("*.txt"),"*.txt");assert_eq!(quote_argument("say \"hi\""),"\"say \\\"hi\\\"\"");assert_eq!(quote_argument("C:\\dir with space\\"),"\"C:\\dir with space\\\\\"");assert_eq!(quote_argument("a\\\\b c"),"\"a\\\\b c\"")}}
